const fmtMoney = (n) => {
  const v = Number(n || 0);
  return new Intl.NumberFormat("es-AR", {
    style: "currency",
    currency: "ARS",
    maximumFractionDigits: 0,
  }).format(v);
};
const fmtMoney1 = (n) => {
  const v = Number(n || 0);
  return new Intl.NumberFormat("es-AR", {
    style: "currency",
    currency: "ARS",
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  }).format(v);
};
const fmtNum = (n) => new Intl.NumberFormat("es-AR").format(Number(n || 0));
const fmtPct = (n, d = 1) => `${Number(n || 0).toFixed(d)}%`;
const toMillions = (n) => Number(n || 0) / 1_000_000;

const monthShort = (mes) => {
  if (!mes || typeof mes !== "string" || !mes.includes("-")) return mes || "";
  const [y, m] = mes.split("-");
  const names = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  return `${names[Number(m) - 1] || m}-${String(y).slice(2)}`;
};

const currentYearMonth = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
};

const buildMonthRange = (startYm, endYm) => {
  const [sy, sm] = startYm.split("-").map(Number);
  const [ey, em] = endYm.split("-").map(Number);
  const result = [];
  let y = sy;
  let m = sm;
  while (y < ey || (y === ey && m <= em)) {
    result.push(`${y}-${String(m).padStart(2, "0")}`);
    m += 1;
    if (m > 12) {
      m = 1;
      y += 1;
    }
  }
  return result;
};

const lerp = (a, b, t) => a + (b - a) * t;

const parseYearMonth = (ym) => {
  if (!ym || typeof ym !== "string" || !ym.includes("-")) return null;
  const [y, m] = ym.split("-").map(Number);
  if (!y || !m) return null;
  return { y, m };
};

const monthDiff = (startYm, endYm) => {
  const s = parseYearMonth(startYm);
  const e = parseYearMonth(endYm);
  if (!s || !e) return null;
  return (e.y - s.y) * 12 + (e.m - s.m);
};

