const normalizeCity = (city) => {
  const c = String(city || "").trim().toLowerCase();
  if (["almirante brown", "brown", "burzaco", "glew", "longchamps", "longchamp", "ministro rivadavia"].includes(c)) return "Almirante Brown";
  if (c === "florencio varela") return "Florencio Varela";
  if (c === "capitan sarmiento" || c === "capitán sarmiento") return "Capitán Sarmiento";
  return city || "Sin ciudad";
};

const parseKmlPolygons = (kml) => {
  const placemarks = [...kml.matchAll(/<Placemark[\s\S]*?<\/Placemark>/g)].map((m) => m[0]);
  const polygons = [];
  placemarks.forEach((placemark, idx) => {
    const nameMatch = placemark.match(/<name>([\s\S]*?)<\/name>/);
    const name = nameMatch ? nameMatch[1].trim() : `Polígono ${idx + 1}`;
    const coordMatches = [...placemark.matchAll(/<coordinates>([\s\S]*?)<\/coordinates>/g)];
    coordMatches.forEach((match, polyIdx) => {
      const coords = match[1]
        .trim()
        .split(/\s+/)
        .map((chunk) => chunk.split(",").map(Number))
        .filter((arr) => arr.length >= 2 && !Number.isNaN(arr[0]) && !Number.isNaN(arr[1]))
        .map(([lng, lat]) => ({ lng, lat }));
      if (coords.length > 2) polygons.push({ name: `${name}${coordMatches.length > 1 ? ` ${polyIdx + 1}` : ""}`, coords });
    });
  });
  return polygons;
};

function MoraMap({ polygons, points }) {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const layerRefs = useRef({});
  const pointsRef = useRef({});
  const [visible, setVisible] = useState({
    habilitado: true,
    bloqueado: true,
    sin_servicio: true,
  });

  const categoryMeta = {
    habilitado: { label: "Habilitados", color: "#1A5FBF", radius: 4 },
    bloqueado: { label: "Bloqueados", color: "#D13030", radius: 6 },
    sin_servicio: { label: "Sin servicio", color: "#5A6A7A", radius: 6 },
  };

  const counts = points.reduce((acc, p) => {
    acc[p.category] = (acc[p.category] || 0) + 1;
    return acc;
  }, {});

  useEffect(() => {
    let cancelled = false
    async function initMap() {
      if (!mapRef.current || mapInstanceRef.current) return;
      const L = await loadLeafletAssets();
      if (!mapRef.current || mapInstanceRef.current) return;

      const map = L.map(mapRef.current, {
        center: [-34.866, -58.363],
        zoom: 14,
        zoomControl: true,
        attributionControl: false,
      });
      mapInstanceRef.current = map;

      L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png", {
        attribution: "© OpenStreetMap © CARTO",
        maxZoom: 19,
        subdomains: "abcd",
      }).addTo(map);

      const coverageLayer = L.layerGroup().addTo(map);
      polygons.forEach((poly) => {
        if (!poly.coords?.length) return;
        L.polygon(
          poly.coords.map((c) => [c.lat, c.lng]),
          {
            color: "#0D7377",
            fillColor: "#0D7377",
            fillOpacity: poly.coords.length > 100 ? 0.07 : 0.12,
            weight: poly.coords.length > 100 ? 2 : 1.5,
            opacity: 0.7,
            dashArray: poly.coords.length > 100 ? null : "5,5",
          }
        ).addTo(coverageLayer);
      });
      layerRefs.current.coverage = coverageLayer;

      const byCategory = {
        habilitado: L.layerGroup().addTo(map),
        bloqueado: L.layerGroup().addTo(map),
        sin_servicio: L.layerGroup().addTo(map),
      };

      points.forEach((p) => {
        const meta = categoryMeta[p.category];
        if (!meta || !Number.isFinite(p.lat) || !Number.isFinite(p.lng)) return;
        L.circleMarker([p.lat, p.lng], {
          radius: meta.radius,
          color: "#ffffff",
          weight: 1,
          fillColor: meta.color,
          fillOpacity: 0.82,
        }).addTo(byCategory[p.category]);
      });

      pointsRef.current = byCategory;

      const bounds = [];
      polygons.forEach((poly) => poly.coords?.forEach((c) => bounds.push([c.lat, c.lng])));
      points.forEach((p) => bounds.push([p.lat, p.lng]));
      if (bounds.length) {
        map.fitBounds(bounds, { padding: [18, 18] });
      }

      setTimeout(() => map.invalidateSize(), 50);
      setTimeout(() => map.invalidateSize(), 250);
    }

    initMap();
    return () => {};
  }, [polygons, points]);

  useEffect(() => {
    const map = mapInstanceRef.current;
    const groups = pointsRef.current;
    if (!map || !groups) return;

    Object.entries(visible).forEach(([key, on]) => {
      const layer = groups[key];
      if (!layer) return;
      if (on && !map.hasLayer(layer)) layer.addTo(map);
      if (!on && map.hasLayer(layer)) map.removeLayer(layer);
    });

    setTimeout(() => map.invalidateSize(), 50);
  }, [visible]);

  return (
    <div>
      <div className="map-filters">
        {Object.entries(categoryMeta).map(([key, meta]) => (
          <label key={key} className="map-filter-item">
            <input
              type="checkbox"
              checked={visible[key]}
              onChange={() => setVisible((prev) => ({ ...prev, [key]: !prev[key] }))}
            />
            <span className="map-dot" style={{ background: meta.color }}></span>
            <span>{meta.label}</span>
          </label>
        ))}
      </div>

      <div className="leg" style={{ marginBottom: 8 }}>
        <span className="li">
          <span className="ld" style={{ background: "#0D7377" }}></span>
          Cobertura red
        </span>
      </div>

      <div className="map-sub">
        {fmtNum(counts.habilitado || 0)} habilitados · {fmtNum(counts.bloqueado || 0)} bloqueados · {fmtNum(counts.sin_servicio || 0)} sin servicio
      </div>

      <div ref={mapRef} className="leaflet-map"></div>

      <div className="map-legend-box">
        <div className="map-legend-title">Capas activas</div>
        {Object.entries(categoryMeta).map(([key, meta]) => (
          <div className="map-legend-row" key={key}>
            <span className="map-dot" style={{ background: meta.color, opacity: visible[key] ? 1 : 0.25 }}></span>
            <span>{meta.label} ({fmtNum(counts[key] || 0)})</span>
          </div>
        ))}
      </div>
    </div>
  );
}


const loadLeafletAssets = async () => {
  if (!document.querySelector('link[data-weconnect-leaflet="1"]')) {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css";
    link.setAttribute("data-weconnect-leaflet", "1");
    document.head.appendChild(link);
  }

  if (window.L) return window.L;

  await new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js";
    script.async = true;
    script.onload = resolve;
    script.onerror = reject;
    document.body.appendChild(script);
  });

  return window.L;
};

